<template><main class="mx-auto max-w-4xl px-4 py-10"><div class="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8"><div class="border-b pb-5"><h1 class="text-3xl font-black">Kialla Computers</h1><p class="mt-1 text-slate-500">Quotation {{q?.quote_number}}</p></div><div v-if="pending" class="py-12 text-center">Loading quote…</div><div v-else-if="error" class="py-12 text-center text-red-700">This quote could not be loaded.</div><template v-else><div class="my-6"><p class="font-bold">Prepared for</p><p>{{q.sales_customers?.full_name}}<span v-if="q.sales_customers?.company_name"> — {{q.sales_customers.company_name}}</span></p><p class="text-sm text-slate-500">Issued {{q.issue_date}} · Valid until {{q.expires_at||'—'}}</p></div><div class="overflow-x-auto"><table class="w-full text-sm"><thead><tr class="border-b"><th class="py-2 text-left">Description</th><th>Qty</th><th class="text-right">Unit Price</th><th class="text-right">Disc.</th><th class="text-right">Total</th></tr></thead><tbody><tr v-for="i in q.manual_quote_items" :key="i.id" class="border-b"><td class="py-3"><b>{{i.product_name}}</b><div class="whitespace-pre-line text-slate-500">{{i.description}}</div></td><td class="text-center">{{i.quantity}}</td><td class="text-right">{{money(i.unit_price)}}</td><td class="text-right">{{Number(i.discount_percent)>0?`${i.discount_percent}%`:'—'}}</td><td class="text-right font-bold">{{money(Number(i.quantity)*Number(i.unit_price)*(1-Number(i.discount_percent||0)/100))}}</td></tr></tbody></table></div><div class="ml-auto mt-6 max-w-sm space-y-2"><div v-if="Number(q.delivery_amount)>0" class="flex justify-between"><span>Delivery</span><b>{{money(q.delivery_amount)}}</b></div><div v-if="Number(q.discount_amount)>0" class="flex justify-between"><span>Quote Discount</span><b>-{{money(q.discount_amount)}}</b></div><div class="flex justify-between border-t pt-3 text-xl"><span>Total</span><b>{{money(q.totals.total)}}</b></div></div><div v-if="['accepted','declined','converted'].includes(q.status)" class="mt-8 rounded-xl bg-slate-100 p-5 text-center"><b v-if="q.status==='accepted'">Thank you — this quote has been accepted.</b><b v-else-if="q.status==='declined'">This quote has been declined.</b><b v-else>This quote has been converted.</b></div><div v-else class="mt-8 rounded-xl border border-blue-100 bg-blue-50 p-5"><h2 class="text-lg font-black">Respond to this quote</h2><p class="mt-1 text-sm text-slate-600">Please accept or decline this quotation.</p><textarea v-model="note" class="mt-4 w-full rounded-lg border border-slate-300 p-3" rows="3" placeholder="Optional message"></textarea><div class="mt-4 flex flex-wrap gap-3"><button class="rounded-lg bg-blue-600 px-5 py-3 font-bold text-white" :disabled="busy" @click="respond('accepted')">Accept Quote</button><button class="rounded-lg border border-slate-300 bg-white px-5 py-3 font-bold" :disabled="busy" @click="respond('declined')">Decline Quote</button></div><p v-if="msg" class="mt-3 font-bold">{{msg}}</p></div></template></div></main></template>
<script setup lang="ts">const route=useRoute(),token=String(route.params.token||''),note=ref(''),busy=ref(false),msg=ref('');const{data:q,pending,error,refresh}=await useFetch<any>(`/api/quotes/public/${token}`);const money=(v:any)=>new Intl.NumberFormat('en-AU',{style:'currency',currency:'AUD'}).format(Number(v||0));async function respond(response:string){busy.value=true;msg.value='';try{await $fetch(`/api/quotes/public/${token}/respond`,{method:'POST',body:{response,note:note.value}});msg.value=response==='accepted'?'Thank you. Your quote has been accepted.':'Your response has been recorded.';await refresh()}catch(e:any){msg.value=e?.data?.statusMessage||e.message||'Unable to save response.'}finally{busy.value=false}}</script>